import React from 'react';
import {AbsoluteFill,useS,T,en,Entrar,Textura,Profundidad,Brillo,Recorrido,seguir,Camara,Chip,Regla,Contador,tono,Paso} from './kit';

// Una célula concreta nace, asciende, se queratiniza y se desprende.
// Los índices reales de las frases se fijan durante la preparación, sin alterar la voz.
export const SUBS={arriba:230,acento:'#E7FF00'};
export const CORTES=[8, 22, 37, 49, 60, 71, 84, 97, 105, 115, 130, 143, 155].map(i=>T(i));
const ACENTOS=[
 {t:en('piel'),s:'pop_01'},{t:en('cuarenta'),s:'ding_01'},
 {t:en('muerta'),s:'whoosh_01'},{t:en('tejas'),s:'pop_02'},
 {t:en('nuevas'),s:'pop_01'},{t:en('empujan'),s:'whoosh_02'},
 {t:en('aplanan'),s:'pop_02'},{t:en('mueren'),s:'ding_01'},
 {t:en('protegen'),s:'pop_01'},{t:en('sueltan'),s:'whoosh_01'},
 {t:en('semanas'),s:'ding_02'},{t:en('mes'),s:'pop_02'},
 {t:en('polvo'),s:'whoosh_02'},{t:en('treinta',2),s:'ding_01'},
 {t:en('polvo',2),s:'pop_01'}];
// El papel acompaña escamas, los pops el relevo celular y los ticks sus fibras.
const familias=[['papel_01','papel_02'],['tick_01','tick_02'],['whoosh_01','whoosh_02'],['papel_03','papel_04'],['pop_01','pop_02'],['whoosh_01','whoosh_02'],['tick_01','tick_02'],['click_01','click_02'],['papel_01','papel_02'],['tick_01','tick_02'],['papel_03','papel_04'],['whoosh_01','whoosh_02'],['papel_01','papel_02'],['papel_03','papel_04']];
const bordes=[0,...CORTES,en('polvo',2)+.5];
export const SFX=[...ACENTOS,...familias.flatMap((f,i)=>Array.from({length:Math.max(0,Math.floor((bordes[i+1]-bordes[i])/.8))},(_,j)=>({t:bordes[i]+j*.8,s:f[j%2]})).filter(v=>ACENTOS.every(a=>Math.abs(a.t-v.t)>=.27)))].sort((a,b)=>a.t-b.t);
const clamp=(x:number)=>Math.max(0,Math.min(1,x));
const Cell:React.FC<{x:number;y:number;flat?:number;hero?:boolean;rot?:number}>=({x,y,flat=0,hero=false,rot=0})=><g transform={`translate(${x} ${y}) rotate(${rot})`}>
 <ellipse cy={22-flat*16} rx={70+flat*35} ry={17-flat*10} fill="#3F222D" opacity=".2"/>
 <ellipse rx={67+flat*30} ry={60-flat*51} fill={flat>.7?'url(#dead)':'url(#cell)'} stroke={hero?'#E7FF00':'#A96568'} strokeWidth={hero?5:2}/>
 <ellipse cx="-18" cy={-16+flat*12} rx="26" ry={12-flat*10} fill="#FFE4CC" opacity=".35"/>
 {flat<.7&&<ellipse cx="7" cy="7" rx={19-flat*16} ry={23-flat*20} fill="#A34A68" opacity={1-flat}/>}
 {Array.from({length:9},(_,i)=><path key={i} d={`M ${-42+i*10} ${-20+flat*18} q 12 15 3 ${40-flat*37}`} fill="none" stroke="#F4D49C" strokeWidth="2" opacity={flat*.9}/>)}
 </g>;
const Arm:React.FC<{s:number;renew?:boolean}>=({s,renew=false})=><g>
 <path d="M -100 1300 C 80 1060 205 750 365 605 C 431 555 510 579 567 628 L 1040 1030 Q 1160 1150 1090 1315 Q 960 1470 810 1395 L 443 1035 Q 305 1160 135 1500 Z" fill="url(#skin)"/>
 <path d="M 28 1270 Q 200 905 377 681 Q 450 636 525 690" fill="none" stroke="#FFE4CA" strokeWidth="11" opacity=".6"/>
 {Array.from({length:130},(_,i)=>{const x=340+(i*73)%550,y=760+(i*47)%470;return <g key={i} opacity=".27"><ellipse cx={x} cy={y} rx="3" ry="2" fill="#824D45"/>{i%4===0&&<path d={`M${x} ${y} q -5 -20 1 -33`} fill="none" stroke="#633B31" strokeWidth="1.5"/>}</g>;})}
 {Array.from({length:17},(_,i)=>{const p=(s*.15+i/17)%1;return <g key={i} transform={`translate(${450+i*27+Math.sin(p*7)*70} ${950-p*520}) rotate(${p*110+i*28})`} opacity={(1-p)*.7}><path d="M-10 -4 Q0 -12 15 0 L6 6 Z" fill={renew?'#F7D6AD':'#D8C8B4'}/></g>;})}
 </g>;
const Layers:React.FC<{s:number;phase:number}>=({s,phase})=>{
 const rise=phase<5?0:clamp((s-en('empujan'))/(en('llegan')-en('empujan')));
 const flat=clamp((s-en('aplanan'))/5);
 const route:[number,number][]=[[500,1310],[560,1140],[475,920],[530,740]];
 return <g>
 <path d="M-40 670 Q300 630 560 675 T1120 670 L1120 1450 L-40 1450Z" fill="url(#dermis)"/>
 <path d="M-30 1350 Q260 1290 510 1350 T1120 1340" fill="none" stroke="#B84665" strokeWidth="45"/>
 {Array.from({length:6},(_,row)=>Array.from({length:9},(_,col)=>{const f=1-row/5;return <Cell key={`${row}-${col}`} x={col*144+(row%2)*64-35} y={750+row*108+Math.sin(col)*8} flat={f} />;}))}
 {Array.from({length:18},(_,i)=><path key={i} d={`M${i*74-80} 1450 Q${i*74+25} 1490 ${i*74+10} 1590`} fill="none" stroke="#DA8B8A" strokeWidth="7" opacity=".5"/>)}
 {phase>=4&&phase<=8&&<Recorrido puntos={route} t0={en('empujan')} t1={en('llegan')} render={(x,y)=> <Cell x={x} y={y} flat={flat} hero/>}/>}
 {phase===8&&<Cell x={540+clamp(s-en('sueltan'))*37} y={700+clamp((s-en('sueltan'))/3)*390} flat={1} hero rot={(s-en('sueltan'))*75}/>}
 {phase===4&&Array.from({length:4},(_,i)=><Cell key={i} x={260+i*180} y={1320-Math.sin(s*2+i)*7} hero={i===2}/>)}
 </g>;
};
const Roof:React.FC<{s:number}>=({s})=><g transform="translate(0 600)">
 <path d="M-20 460 L540 40 1120 460 1120 680 -20 680Z" fill="#58443B"/>
 {Array.from({length:5},(_,row)=>Array.from({length:8},(_,col)=><g key={`${row}-${col}`} transform={`translate(${col*153-30+(row%2)*50} ${200+row*90}) rotate(-7)`}>
 <path d="M0 0 L145 0 135 95 Q60 120 0 95Z" fill="url(#dead)" stroke="#9D836F" strokeWidth="4"/>
 <path d="M12 10 L130 10" stroke="#FFEBD3" strokeWidth="6"/>
 </g>))}
 <Cell x={570} y={210+((s-en('tejas'))%3)*130} flat={1} hero rot={(s-en('tejas'))*17}/>
 </g>;
const DustRoom:React.FC<{s:number;wipe?:boolean}>=({s,wipe=false})=><g>
 <path d="M30 350 H330 V950 H30Z" fill="#A2B9B9"/>
 <path d="M175 350V950 M30 650H330" stroke="#644D40" strokeWidth="25"/>
 <path d="M90 360 L1000 1120 1010 1590 70 760Z" fill="#F5D49A" opacity=".14"/>
 <path d="M-20 1210 L970 1030 1110 1330 65 1560Z" fill="url(#wood)"/>
 {Array.from({length:24},(_,i)=><path key={i} d={`M ${i*58-80} 1210 q 80 -100 130 230`} fill="none" stroke="#E7B67B" strokeWidth="2" opacity=".2"/>)}
 {Array.from({length:70},(_,i)=><ellipse key={i} cx={(i*139+s*(4+i%3))%1080} cy={500+(i*67+s*9)%970} rx={i%3+1} ry={i%3+2} fill="#F8E1B5" opacity=".6"/>)}
 {wipe&&<g transform={`translate(${Math.min(700,(s-en('Dale'))*100)} 1180)`}>
 <path d="M-360 80 Q-80 -15 30 20 Q75 28 57 58 L-10 80 55 90 Q80 105 52 129 L-55 146 -330 220Z" fill="url(#skin)"/>
 <path d="M-450 175 Q-220 100 -15 75" fill="none" stroke="#513728" strokeWidth="18" opacity=".6"/>
 <ellipse cx="29" cy="39" rx="17" ry="9" fill="#E7B6A1" transform="rotate(-15 29 39)"/>
 </g>}
 </g>;
export const Escena:React.FC=()=>{
 const {s}=useS();
 const ts=[0,...CORTES];
 const b=Math.max(0,ts.findIndex((t,i)=>s>=t&&(i===ts.length-1||s<ts[i+1])));
 const bg=tono(s,[0,en('No'),en('polvo'),en('Mientras')],['#7F493D','#703744','#6F5139','#7F493D']);
 const outside=<Arm s={s}/>;
 const inside=<Layers s={s} phase={b}/>;
 let drawing:React.ReactNode;
 if(b<=1||b===12)drawing=<Arm s={s}/>;
 else if(b===2)drawing=<Entrar t={en('No')-.2} x={530} y={900} dur={1.2} zoom={12} fuera={outside} dentro={inside}/>;
 else if(b===3)drawing=<Roof s={s}/>;
 else if(b<=10)drawing=<Layers s={s} phase={b}/>;
 else drawing=<DustRoom s={s} wipe={b===13}/>;
 const drift=1+(s%6)*.006;
 return <AbsoluteFill>
 <Textura tipo={b>=11&&b!==12?'fibra':'piel'} base={`radial-gradient(ellipse at 40% 43%, ${bg}, #231B22)`} linea="#9C6C59" luz="rgba(255,220,189,.2)" semilla={13}/>
 <Brillo x={500} y={900} r={490} color="#EDAB70"/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute',inset:0}}>
 <defs>
 <linearGradient id="skin" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#FAD1AA"/><stop offset=".45" stopColor="#F2B48C"/><stop offset="1" stopColor="#9F5F4D"/></linearGradient>
 <radialGradient id="cell" cx="30%" cy="25%"><stop stopColor="#FFB7AE"/><stop offset=".6" stopColor="#E86F7A"/><stop offset="1" stopColor="#A64C64"/></radialGradient>
 <linearGradient id="dead" x2="0" y2="1"><stop stopColor="#EADCBD"/><stop offset="1" stopColor="#A99D8B"/></linearGradient>
 <linearGradient id="dermis" x2="0" y2="1"><stop stopColor="#9F6B5B"/><stop offset=".45" stopColor="#E2A18F"/><stop offset="1" stopColor="#A6526D"/></linearGradient>
 <linearGradient id="wood"><stop stopColor="#AD7E51"/><stop offset="1" stopColor="#58402E"/></linearGradient>
 </defs>
 <g transform={`translate(${Math.sin(s*.3)*8} ${Math.cos(s*.4)*6}) translate(540 1000) scale(${drift}) translate(-540 -1000)`}>{drawing}</g>
 </svg>
 {b===1&&<><Contador hasta={40000} t0={en('treinta')} t1={en('células')} x={540} y={490}/><Chip texto="por minuto" x={540} y={610} t0={en('minuto')} color="#E7FF00"/></>}
 {b===2&&<Chip texto="ya muerta" x={700} y={690} t0={en('muerta',2)} color="#E7FF00"/>}
 {b===9&&<Regla x={850} y={760} largo={520} t0={en('semanas')} texto="4 semanas" vertical color="#E7FF00"/>}
 {b===10&&<Chip texto="capa nueva" x={540} y={550} t0={en('mes')} color="#E7FF00"/>}
 {b===12&&<Contador hasta={30000} t0={en('treinta',2)} t1={en('más',2)} x={540} y={530}/>}
 <Profundidad color="rgba(45,22,18,.25)" lejos="rgba(255,231,201,.09)" semilla={18}/>
 </AbsoluteFill>;
};
